import mapAsyncLimit from './mapAsyncLimit';

const sleep = (ms: number) => new Promise<void>(r => setTimeout(r, ms));

describe('mapAsyncLimit (TS)', () => {
  test('keeps output order', async () => {
    const res = await mapAsyncLimit<number, number>([15, 5, 10], 2, async (ms) => { await sleep(ms); return ms / 5; });
    expect(res).toEqual([3, 1, 2]);
  });

  test('caps concurrency', async () => {
    const items = [20, 20, 20, 20];
    let active = 0, maxActive = 0;
    const res = await mapAsyncLimit<number, number>(items, 2, async (ms) => {
      active++; if (active > maxActive) maxActive = active;
      await sleep(ms);
      active--; return ms;
    });
    expect(res).toEqual(items);
    expect(maxActive <= 2).toEqual(true);
  });

  test('fail-fast rejects on first error', async () => {
    let threw = false;
    try {
      await mapAsyncLimit<number, number>([5, 10, 5], 2, async (ms, idx) => {
        await sleep(ms);
        if (idx === 1) throw new Error('boom');
        return idx;
      }, 'fail-fast');
    } catch (e: any) {
      threw = true;
      expect(e && e.message).toEqual('boom');
    }
    expect(threw).toEqual(true);
  });

  test('all-settled returns settled outcomes', async () => {
    const res = await mapAsyncLimit<number, number>([5, 10, 5], 2, async (ms, idx) => {
      await sleep(ms);
      if (idx === 1) throw new Error('x');
      return idx * 2;
    }, 'all-settled') as Array<{ status: 'fulfilled' | 'rejected'; value?: number; reason?: any }>;

    expect(res[0]).toEqual({ status: 'fulfilled', value: 0 });
    expect(res[1].status).toEqual('rejected');
    expect(typeof (res[1] as any).reason).toEqual('object');
    expect(res[2]).toEqual({ status: 'fulfilled', value: 4 });
  });

  test('throws on invalid limit', () => {
    let threw = false;
    try { mapAsyncLimit<number, number>([1], 0, async (x) => x); } catch { threw = true; }
    expect(threw).toEqual(true);
  });
});

